/**
 * Discounted Cumulative Gain at K.
 * Uses the standard formula: DCG@K = sum_{i=1..K} (2^grade_i - 1) / log2(i + 1).
 */
export function dcgAtK(retrieved: string[], graded: Map<string, number>, k: number): number {
  let dcg = 0;
  const limit = Math.min(k, retrieved.length);
  for (let i = 0; i < limit; i++) {
    const grade = graded.get(retrieved[i]!) ?? 0;
    dcg += (Math.pow(2, grade) - 1) / Math.log2(i + 2);
  }
  return dcg;
}

