import type { PoolEntry, PoolSourceHit, QueryOrigins, RankerId } from './types.js';
import { RANKER_IDS } from './types.js';

export interface BuiltPool {
  /** Grader-facing rows: deduplicated, blinded order, no ranker/rank/score field. */
  entries: PoolEntry[];
  /** Scorer-only: each ranker's own ordered chunk_ref list, never shown to the grader. */
  origins: QueryOrigins;
}

/**
 * Forms the deduplicated union of both rankers' top-N hits for one query,
 * in an order that reveals nothing about which ranker(s) surfaced a chunk or
 * at what rank (the issue's blinding requirement): entries are sorted by
 * `chunk_ref` alone, which is neither ranker's own rank order and is
 * independent of relevance. `origins` records each ranker's real order
 * separately, read only by the scorer.
 */
export function buildPool(queryId: string, query: string, rankerHits: Record<RankerId, PoolSourceHit[]>): BuiltPool {
  const seen = new Map<string, PoolSourceHit>();
  for (const rankerId of RANKER_IDS) {
    for (const hit of rankerHits[rankerId]) {
      if (!seen.has(hit.chunk_ref)) seen.set(hit.chunk_ref, hit);
    }
  }

  const entries: PoolEntry[] = [...seen.values()]
    .sort((a, b) => a.chunk_ref.localeCompare(b.chunk_ref))
    .map((hit) => ({ ...hit, query_id: queryId, query }));

  const origins: QueryOrigins = {
    query_id: queryId,
    rankers: {
      bm25: rankerHits.bm25.map((h) => h.chunk_ref),
      weighted: rankerHits.weighted.map((h) => h.chunk_ref),
    },
  };

  return { entries, origins };
}
