/**
 * For one query, the "ideal" (IDCG) denominator must be the SAME for every
 * ranker being compared: the full set of human-graded chunks pooled for
 * that query, regardless of which ranker(s) surfaced them (standard nDCG
 * practice — a ranker that misses a relevant chunk entirely is penalized
 * against the query's real relevance set, not let off the hook by only
 * being judged against what it happened to retrieve). This builds that
 * shared graded map once per query, from the union of both rankers'
 * retrieved chunk_refs.
 */
function sharedGradedMap(origins: QueryOrigins, labels: Map<string, LabelRecord>): Map<string, number> {
  const graded = new Map<string, number>();
  const allChunkRefs = new Set<string>();
  for (const rankerId of RANKER_IDS) {
    for (const chunkRef of origins.rankers[rankerId]) allChunkRefs.add(chunkRef);
  }
  for (const chunkRef of allChunkRefs) {
    const record = labels.get(labelKey(origins.query_id, chunkRef));
    if (record) graded.set(chunkRef, record.grade);
  }
  return graded;
}

